fragments.new:
static func canRepair(_ card: RecipeCard) -> Bool {
    RecipeQuality.isGenerated(card) && !RecipeQuality.shortfall(card).isEmpty
}

static func servingsAreUnspecified(_ recipe: RecipeCard) -> Bool {
    recipe.servings == 0 && recipe.isEditableDraft
}

fragments.old:
Button { Task { await rewrite(recipe, repairQuality: true) } } label: {
    Label("Repair these gaps", systemImage: "wand.and.sparkles")
}.buttonStyle(.ate(.secondary, height: 40)).disabled(asking).accessibilityIdentifier("improveWithAI")

fragments.new:
if RecipeDraftRepair.canRepair(recipe) {
    Button { Task { await rewrite(recipe, repairQuality: true) } } label: {
        Label("Repair these gaps", systemImage: "wand.and.sparkles")
    }.buttonStyle(.ate(.secondary, height: 40)).disabled(asking).accessibilityIdentifier("improveWithAI")
}

if RecipeNutritionCalculator.servingsAreUnspecified(recipe) {
    return "Add the number of servings to estimate nutrition. Ate won't guess it."
}
